using System.Windows;
using ParadoxModTool.Localization;

namespace ParadoxModTool.App;

/// <summary>
/// Anleitung zu den Patch-Rezepten mit Inhaltsverzeichnis und Suche. Durchgehendes Beispiel ist Angkor Wat
/// (CK III: Special Building in ein normales Gebäude verwandeln).
/// </summary>
public sealed class PatchRecipeHelpWindow : GuideWindow
{
    /// <summary>Die Blöcke in der geladenen Oberflächensprache; bei jedem Öffnen neu gebaut, damit die Sprache stimmt.</summary>
    private static GuideBlock[] Blocks => new[]
    {
        new GuideBlock(GuideBlockKind.Title, T("patchhelp.title", "Anleitung: Patch-Rezepte")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.intro.heading", "Wozu Patch-Rezepte?")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.intro.what", "Manche Änderungen an einer Mod folgen in vielen Dateien demselben Muster. Beispiel: Jedes Special Building soll ein normales Gebäude werden. Dafür kommentierst du in der History die Slot-Zeile aus, kopierst den Gebäudeblock aus Vanilla, entfernst type = special, trägst das Gebäude bei den Holdings ein und so weiter, für jedes Gebäude einzeln.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.intro.how", "Ein Patch-Rezept beschreibt diese Arbeit einmal: als Tabelle (was) und Regeln (wie). PMT erledigt sie dann für alle Zeilen der Tabelle. Nach einem Vanilla-Update wendest du das Rezept einfach erneut an.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.intro.where", "Rezepte gehören zu einer Mod, liegen aber außerhalb ihres Ordners: im Speicherort von PMT (Standard: Dokumente\\Paradox Modding Tool) im Ordner „<Modname> Patch Recipes“, neben den Snapshots. So werden sie nie mit hochgeladen. Rezepte aus dem früheren Ordner .pmt-patches in der Mod holt PMT beim Öffnen automatisch dorthin.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.steps.heading", "Ablauf in vier Schritten")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.steps.list", "1. Rezept: Mod wählen, dann „Neues Rezept“.\n2. Tabelle: eine Zeile pro Ding, das du ändern willst (zum Beispiel pro Gebäude), mit Spalten für alles, was je Zeile anders ist.\n3. Regeln: was mit jeder Zeile passieren soll.\n4. Vorschau: die Regeln probeweise laufen lassen, das Ergebnis prüfen, dann „Anwenden“.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.steps.safety", "Bis zum Anwenden schreibt PMT nichts. Vor dem Anwenden sichert PMT die Mod. Im Hauptfenster nimmt „Rückgängig“ den ganzen Lauf in einem Schritt zurück.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.ai.heading", "Mit KI erstellen"), "patchhelp.ai"),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.intro", "Ein Rezept von Hand zu bauen heißt: deine Arbeit in Spalten, Zeilen und Regeln übersetzen. „Mit KI erstellen“ (neben „Neues Rezept“) gibt genau diese Übersetzung an eine KI deiner Wahl ab. Du musst das Rezept nicht lesen können: Du beurteilst es an seiner Erklärung und an der Vorschau, die zeigt, was es in deiner Mod ändern würde.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.steps", "In fünf Schritten:\n1. Mod wählen und Beispiel-Dateien anhaken: was du bisher von Hand änderst, aus der Mod (dein Ergebnis) und mit dem Umschalter „Spieldateien“ die Vanilla-Vorlage dazu. Bei großen Dateien unter „Codeblöcke“ nur die passenden Stellen einfügen.\n2. Beschreiben, was dein Feature tut und welche Arbeit sich nach jedem Vanilla-Update wiederholt.\n3. „Als Text kopieren“ und in eine Chat-KI einfügen, „Als Datei speichern“ zum Hochladen oder „Als Ordner speichern“ für eine KI mit Dateizugriff.\n4. Die Antwort der KI unter „Ergebnis“ einfügen und „Übernehmen“ drücken (oder „Aus Ordner importieren“).\n5. PMT prüft und speichert das Rezept, zeigt oben seine Erklärung und öffnet die Vorschau. Gefällt dir, was sich ändern würde, drückst du „Anwenden“. Sonst „Fehler für die KI kopieren“ und der KI zurückgeben.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.result", "Fehler im Rezept stoppen den Import, dann wird nichts gespeichert. Warnungen, übersprungene Zeilen und Konflikte der Vorschau stehen in den Meldungen. „Fehler für die KI kopieren“ gibt sie der KI als einen Text zurück; sie korrigiert dann das ganze Rezept.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.explanation", "Die Erklärung steht oben im Fenster Patch-Rezepte unter „Erklärung“. Die KI schreibt dort in deiner Sprache, was das Rezept tut, wie sie die Zeilen gefunden hat und was die Mechanik nicht kann. Du kannst sie ändern; sie ändert nichts an der Mod.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.handOver", "Mit „Offenes Rezept mitgeben“ ändert die KI das gewählte Rezept, statt ein neues zu bauen. Sie muss dabei die Kennung des Rezepts und die Kennungen der Regeln behalten, denn daran hängen die erzeugten Bereiche und deine Handänderungen. Beim Übernehmen der Antwort zählt, ob das Häkchen gesetzt und ein Rezept derselben Mod im Fenster Patch-Rezepte gewählt ist, auch in einem neu geöffneten KI-Fenster. Trägt die Antwort die Kennung eines Rezepts dieser Mod, gilt sie als neue Fassung dieses Rezepts, auch wenn inzwischen ein anderes gewählt ist; eine unbekannte Kennung setzt PMT auf die des gewählten Rezepts zurück. Dann schlägt PMT „Ersetzen“ vor. Fehlen Regeln, die schon Text in der Mod erzeugt haben, fragt PMT nach: Dieser Text bliebe in der Mod und müsste von Hand entfernt werden. „Nein“ lässt das bisherige Rezept unverändert.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.tips", "Tipps:\n• Die wiederkehrende Arbeit beschreiben, nicht die Rezept-Technik: was du nach jedem Update tust und was am Ende in der Mod stehen soll.\n• Ein fertiges Beispiel mitgeben, z. B. ein Gebäude, das du schon von Hand umgebaut hast, und die Vanilla-Datei dazu.\n• Klein anfangen: erst eine Regel oder wenige Zeilen, dann erweitern.\n• Nach der Vorschau urteilen: Jede Datei zeigt links den aktuellen Text und rechts das Ergebnis. Erst „Anwenden“ schreibt, und „Rückgängig“ nimmt den ganzen Lauf zurück.\n• Sagt die KI in der Erklärung, dass etwas nicht geht, ist das ehrlich gemeint: Diesen Teil erledigst du weiter von Hand.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.ai.cli", "Für KIs mit Dateizugriff liegt pmt-patch.exe im Programmordner. Die Datei task.md im Auftragsordner nennt die Befehle mit den echten Pfaden: check prüft das Rezept, plan zeigt, was es in der Mod ändern würde. Beide schreiben nichts in Mod, Spiel oder Rezeptordner.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.table.heading", "Die Tabelle")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.key", "Jede Zeile hat einen Schlüssel (Spalte key), zum Beispiel angkor_wat_01. Er muss eindeutig sein.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.own", "Eigene Spalten legst du unter „Spalten“ an: Name, Art (Text, Zahl oder Liste) und Standardwert. Eine leere Zelle nutzt den Standardwert, er steht grau in der Zelle. Die Werte einer Liste trennst du mit Kommas.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.derived", "Abgeleitete Spalten tippst du nicht. PMT schlägt sie in den Spieldateien nach. Sie sind grau und lassen sich nicht bearbeiten.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.table.derivedBox", "Spalte provinz (abgeleitet)\n  Dateien:  history/provinces/*.txt\n  Quelle:   Vanilla\n  Suche:    special_building_slot = {key}\n  Nehmen:   äußerster Block\n\nSpalte barony (abgeleitet, Titel prüfen)\n  Dateien:  common/landed_titles/**/*.txt\n  Quelle:   Vanilla\n  Suche:    province = {provinz}\n  Nehmen:   innerster Block\n\nErgebnis für angkor_wat_01:\n  provinz = 10816      (der Block, in dem der Slot steht)\n  barony  = b_angkor   (der Block, in dem province = 10816 steht)")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.order", "Eine abgeleitete Spalte darf frühere Spalten nutzen, so wie barony hier {provinz} nutzt. Deshalb zählt die Reihenfolge der Spalten.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.source", "Quelle: „Vanilla“ sucht in den Spieldateien, „Mod“ nur in deiner Mod, „Mod vor Vanilla“ zuerst in der Mod. „Optional“ heißt: Nicht gefunden ergibt einen leeren Wert statt eines Fehlers.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.files", "Im Feld „Dateien“ trennst du mehrere Muster mit ;, zum Beispiel history/provinces/*.txt;events/flogi_events.txt. Das gilt für Spalten und Regeln.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.all", "Mehrere Suchen trennst du mit ; (es zählt jede). Mit „Alle Treffer (Liste)“ liefert eine abgeleitete Spalte alle Fundstellen als Liste statt nur der ersten. Spätere Spalten, die sie benutzen, suchen dann je Wert.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.errors", "Rot markierte Zeilen haben einen Fehler, der Grund steht in der Spalte „Hinweis“:\n• Der Schlüssel fehlt oder kommt doppelt vor.\n• Ein abgeleiteter Wert wurde nicht gefunden (außer bei „Optional“).\n• Ein Titel in einer Spalte mit „Titel prüfen“ existiert nicht, zum Beispiel b_bamiyan.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.table.skip", "Rote Zeilen überspringt PMT bei allen Regeln mit Geltung „pro Zeile“. Was diese Zeilen früher erzeugt haben, bleibt stehen. Alle anderen Zeilen laufen normal. „Nur Einträge mit Fehlern“ zeigt nur die roten Zeilen.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.placeholders.heading", "Platzhalter")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.placeholders.intro", "In den Feldern Suche, Block, Text, Liste (Pfad) und Eintrag setzt PMT für jede Zeile die Werte ein. Dateien, Quelle, Ziel, Innerhalb und Ersatz bleiben, wie sie stehen:")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.placeholders.box", "{key}                    Schlüssel der Zeile\n{spalte}                 Wert der Spalte, zum Beispiel {barony}\n{?spalte}Text{/spalte}   Text nur, wenn die Spalte einen Wert hat\n{!spalte}Text{/spalte}   Text nur, wenn die Spalte leer ist")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.placeholders.list", "Eine Listen-Spalte in Liste (Pfad), Eintrag, Suche oder im Text einer Vorlage erzeugt je Wert ein eigenes Ziel; in Block und Bearbeitungen steht dagegen die ganze Liste. Mit holdings = castle_holding, city_holding wirkt {holdings}/buildings auf beide Holdings.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.placeholders.repeat", "{*spalte}Text{/spalte} wiederholt den Text einmal je Listenwert, darin steht {spalte} für den einzelnen Wert. Die Vorlage nutzt das für OR = { barony = title:… }.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.placeholders.empty", "Ein unbekannter Platzhalter ist ein Fehler im Regel-Editor. Ist ein Wert leer, überspringt die Regel diese Zeile. Die Vorschau nennt den Grund („leerer Wert für …“).")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.rules.heading", "Die Regelarten")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.order", "Die Regeln laufen von oben nach unten. Geltung „pro Zeile“ läuft für jede Tabellenzeile, „einmal (global)“ einmal für das ganze Rezept. Der Haken „Aktiv“ schaltet eine Regel ab, ohne sie zu löschen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.lines", "Zeilen: sucht Zeilen in Dateien deiner Mod und ändert sie.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.rules.linesBox", "Dateien:  history/provinces/*.txt\nSuche:    special_building_slot = {key}\nAktion:   Auskommentieren\n\nVorher:   special_building_slot = angkor_wat_01\nNachher:  #special_building_slot = angkor_wat_01")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.linesActions", "Aktionen: Auskommentieren, Löschen, Ersetzen (nur der gefundene Text) und Block entfernen (der ganze Block mit diesem Schlüssel; mit „Folgestufen mitnehmen“ auch alle Stufen über next_building). Mit „Kopie aus Vanilla anlegen, wenn sie fehlt“ legt PMT die Mod-Datei zuerst aus Vanilla an. Suchart „Text“ trifft nur ganze Wörter und sieht über Leerzeichen hinweg: province trifft nicht every_province.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.linesMulti", "Die Aktion Ersetzen mit Suchart „Text“ findet auch Treffer über mehrere Zeilen. Ein Block in Mehrzeilform (building_requirement_castle_city_church =, Zeilenumbruch, { LEVEL = 03 } darunter) wird wie die Einzeilform ersetzt; Kommentare bleiben unberührt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.blockCopy","Block-Kopie: kopiert einen Block aus Vanilla in deine Mod und ändert ihn dabei.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.blockCopyInsert", "„Einfügen in“ fügt Text nur hinzu und ersetzt nichts: Gibt es den Block (z. B. on_start) nicht, legt PMT ihn an, sonst kommt der Text an sein Ende. Bei übernommenen Blöcken fügt PMT nur die Zeilen ein, die noch fehlen. „Einfügen nach“, „Am Anfang einfügen“ und „Am Ende einfügen“ wählen eine andere Stelle.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.rules.blockCopyBox","Quelle:  common/buildings/00_special_buildings.txt, Block {key}\nZiel:    common/buildings/zz_special_buildings.txt\nBearbeitungen:\n  Eigenschaft entfernen:  type\n  Einfügen in:            can_construct_potential\n                          {?barony}barony = title:{barony}{/barony}\n\nErgebnis für angkor_wat_01:\nangkor_wat_01 = {\n    construction_time = very_slow_construction_time\n    ...\n    can_construct_potential = {\n        building_requirement_tribal = no\n        barony = title:b_angkor\n    }\n}")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.blockEdit", "Block bearbeiten: ändert einen Block direkt in den bestehenden Dateien deiner Mod, ohne Kopie und ohne eigene Zieldatei. Die Bearbeitungen sind dieselben wie bei der Block-Kopie. Steht der Block nur in Vanilla, legt PMT mit „Kopie aus Vanilla anlegen, wenn sie fehlt“ zuerst die Mod-Datei an. Mit „Folgestufen mitnehmen“ gilt die Regel für alle Stufen über next_building. PMT fügt nur Zeilen ein, die noch fehlen; ein zweiter Lauf ändert nichts.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.template","Vorlage: schreibt für jede Zeile einen eigenen Text in eine Datei, wahlweise in einen bestimmten Block („Innerhalb“).")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.rules.templateBox", "Ziel:       common/scripted_effects/sort_buildings_effects.txt\nInnerhalb:  Sort_buildings_add_buildings/hidden_effect\nText:       if = {\n                limit = { has_building = {key} }\n                # was für jedes Gebäude passieren soll\n            }")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.list", "Liste: trägt einen Eintrag in eine Liste ein, wenn er dort fehlt.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.rules.listBox", "Ziel:     common/holdings/00_holdings.txt\nListe:    {holdings}/buildings\nEintrag:  {key}\n\nErgebnis: castle_holding = { buildings = { ... angkor_wat_01 } }\n          city_holding   = { buildings = { ... angkor_wat_01 } }")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.showResult", "„Ergebnis zeigen“ zeigt, was die gewählte Regel für die Zeile unter „Vorschau für“ ändert: links aktuell, rechts nach dem Anwenden. So prüfst du eine Regel, ohne die ganze Vorschau zu berechnen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.options", "Zwei Optionen: „Nur Dateien, die es auch in Vanilla gibt“ (Zeilen) wirkt nur auf Mod-Kopien von Vanilla-Dateien und schützt eigene Dateien im selben Ordner. „Bestehende Blöcke übernehmen“ (Block-Kopie) erklärt der Abschnitt zur Vorlage.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.rules.wholeRows", "„Zeilen ganz oder gar nicht“ (unter der Regelliste): Überspringt eine Regel eine Zeile, lassen alle Regeln sie aus. Die Vorschau nennt den Grund („ausgelassen wie in Regel …“).")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.preview.heading", "Vorschau und Anwenden")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preview.compute", "„Vorschau berechnen“ lässt alle aktiven Regeln auf einer Kopie im Speicher laufen. Jede Datei bekommt einen Status: neu, geändert, Konflikt oder unverändert.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preview.files", "Ein Klick auf eine Datei zeigt links den aktuellen Text, rechts das Ergebnis. Markierst du rechts Zeilen und drückst U, nimmt PMT diese Änderung zurück. Unter der Liste stehen übersprungene Zeilen und Warnungen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preview.apply", "„Anwenden“ schreibt alle Dateien auf einmal. PMT verweigert das, wenn sich Dateien seit der Vorschau geändert haben oder ungespeichert im Editor offen sind. Dann speichern und die Vorschau neu berechnen.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.watch.heading", "Der Wächter")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.watch.intro", "Der Reiter „Wächter“ zeigt alle Dateien in Vanilla und in deiner Mod, die ein Suchmuster oder einen Schlüssel der Tabelle verwenden. So findest du Stellen, die dein Rezept noch nicht erfasst, auch nach einem Vanilla-Update. Die Suchmuster legst du unter „Suchmuster“ fest, die Schlüssel der Tabellenzeilen sucht der Wächter immer mit. Kommentare und die vom Rezept erzeugten Bereiche zählen nicht.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.watch.statusBox", "nicht abgedeckt  Nach dem Anwenden bleibt ein Treffer übrig, oder Vanilla trifft\n                 und die Mod bekommt keine Kopie.\n                 Aktion: Kopie anlegen + Regel, Ignorieren\nveraltet         Das Update-Tool würde die Mod-Kopie bei\n                 „Merge nach Spiel-Update“ anbieten.\n                 Aktion: Im Update-Tool öffnen\neigene Datei     Datei nur in deiner Mod, mit Treffern.\n                 Aktion: Öffnen (springt zur Zeile)\nabgedeckt        Nach dem Anwenden ist kein Treffer mehr übrig.\nignoriert        Von dir ausgeblendet, mit Notiz.\n                 Aktion: Nicht mehr ignorieren")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.watch.copy", "„Kopie anlegen + Regel“ ändert nur das Rezept: Die Datei kommt in eine Zeilen-Regel deiner Wahl, dort wird „Kopie aus Vanilla anlegen“ eingeschaltet. Die Kopie entsteht beim nächsten Anwenden. „Neue Zeilen-Regel (aus)“ legt eine Regel für die Datei an, die noch ausgeschaltet ist. Prüfe Suche und Aktion, bevor du sie einschaltest: „Auskommentieren“ einer Zeile mit { würde die Datei zerstören.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.watch.copyNarrow", "Hat die gewählte Regel ein Dateimuster mit * und legt sie noch keine Kopien an, legt PMT direkt dahinter eine gleiche Regel nur für diese Datei an. So wird nur diese eine Datei aus Vanilla kopiert, nicht jede Datei, die das Muster trifft.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.watch.folder", "„Ordner ignorieren“ ignoriert alle Dateien im Ordner der gewählten Datei samt Unterordnern, z. B. common/customizable_localization, in einem Schritt. „Nicht mehr ignorieren“ auf einer dieser Dateien hebt die Ordner-Regel auf; dann zählen alle Dateien des Ordners wieder.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.watch.rescan", "Der Wächter scannt beim ersten Öffnen des Reiters und auf „Neu scannen“. Ändern sich Regeln, Zeilen oder Suchmuster, steht oben „Rezept geändert, neu scannen“. Ignorieren wirkt sofort. „Erledigte ausblenden“ blendet abgedeckte und ignorierte Dateien aus. Ein Doppelklick auf eine Fundstelle öffnet die Datei an dieser Zeile.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.memory.heading", "Erzeugte Bereiche und deine Handänderungen")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.memory.markers", "Block-Kopie und Vorlage schreiben zwischen Marken:")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.memory.markersBox", "# PMT-Patch special_buildings/gebaeude begin\n# PMT-Unit angkor_wat_01\nangkor_wat_01 = {\n    ...\n}\n# PMT-Unit borobudur_01\nborobudur_01 = {\n    ...\n}\n# PMT-Patch special_buildings/gebaeude end")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.memory.edit", "Den Text zwischen den Marken darfst du von Hand ändern, die Markenzeilen selbst nicht. Löschst du eine PMT-Unit-Zeile samt Block, gilt der Baustein als von Hand gelöscht und PMT erzeugt ihn nicht neu.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.memory.merge", "PMT merkt sich, was es zuletzt geschrieben hat. Beim nächsten Lauf:\n• Hast du den Baustein nicht geändert, ersetzt PMT ihn durch die neue Fassung.\n• Hast du ihn geändert, führt PMT deine Änderung und die neue Fassung zusammen.\n• Ändern beide dieselbe Stelle, zeigt die Vorschau einen Konflikt: links deine Fassung, rechts neu erzeugt. Übernimm mit U, was bleiben soll, dann „Als gelöst übernehmen“.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.memory.lists", "Bei Listen entfernt PMT nur Einträge, die es selbst eingefügt hat. Einträge, die schon vorher da waren, rührt es nie an.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.memory.limit", "Grenze: Zeilen-Regeln haben kein Gedächtnis. Was du in der Vorschau mit U zurücknimmst, kommt beim nächsten Lauf wieder. Schalte dafür die Regel ab oder ändere ihre Suche.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.update.heading", "Nach einem Vanilla-Update")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.update.steps", "1. Im Compare und Update Tool „Merge nach Spiel-Update“ ausführen.\n2. Hat die Mod Rezepte, fragt PMT danach, ob es sie öffnen soll.\n3. Vorschau berechnen, prüfen, Anwenden.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.update.result", "So landen neue Vanilla-Inhalte, zum Beispiel geänderte Baukosten, in deinen erzeugten Blöcken. Deine Handänderungen bleiben erhalten.")),

        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.update.watch", "Danach im Wächter „Neu scannen“: Neue Fundstellen aus Vanilla erscheinen als „nicht abgedeckt“.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.preset.heading", "Vorlage: Special Buildings in normale Gebäude")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.intro", "Für CK III bietet „Neues Rezept“ die Vorlage „Special Buildings in normale Gebäude“. Sie legt die Spalten holdings, provinz und barony an, fünf Regeln in fester Reihenfolge und die Suchmuster des Wächters. provinz und barony suchen alle vier Formen in der History und alle Orte.")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.preset.rulesBox", "slots       Slot-Zeilen in der History auskommentieren (alle vier Formen)\niterators   every_/any_/random_/ordered_special_building_province ersetzen,\n            Dateien fügst du über den Wächter hinzu\noriginals   Original-Definitionen aus den Mod-Kopien der Vanilla-Dateien entfernen\nbuildings   Gebäude aus Vanilla kopieren, type = special entfernen,\n            OR = { barony = title:… } in can_construct_potential einfügen\nholdings    Gebäude bei den Holdings eintragen")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.resource", "Zusätzlich zu den fünf Regeln legt die Vorlage vier Regeln trigger_level_01 bis trigger_level_04 an und erweitert die Block-Kopie. Beides gehört zur Mod „Flogi's Buildings and Technology Mod“:\n• Die Block-Kopie fügt in jedes umgewandelte Gebäude (jede Ausbaustufe) in on_start die Effekte flogis_techmod_subtract_wood/stone/metal/luxury_250 und in on_cancelled flogis_techmod_add_wood/stone/metal/luxury_250 ein. Gibt es on_start oder on_cancelled schon, kommen die Zeilen hinein, bei übernommenen Blöcken nur die fehlenden.\n• Die vier Regeln ersetzen in den erzeugten Gebäuden building_requirement_castle_city_church = { LEVEL = 01 } bis 04 durch building_requirement_main_building = { LEVEL = 2 }, 4, 6 und 8, in Einzeilform und Mehrzeilform.\nBrauchst du das nicht, schalte die vier Regeln und in der Block-Kopie die beiden Bearbeitungen „Einfügen in“ mit on_start und on_cancelled aus.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.import","„Specials aus Vanilla einlesen“ in der Tabelle listet alle Specials aus Vanilla, die eine Ausbaukette beginnen. Du siehst die gefundenen Baronien, ob deine Mod das Gebäude noch als Special definiert und ob es schon eine Zeile ist. Nichts ist vorgewählt. „Nur in Mod noch Special“ zeigt die Gebäude, die du noch umbauen kannst.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.adopt", "Steht ein Gebäude schon in deiner Mod, meldet die Vorschau „bereits definiert“ und bietet „Bestehende Blöcke übernehmen“ an. PMT holt dann deinen Block in den erzeugten Bereich, baut ihn um (type = special raus, Baronie rein) und entfernt ihn aus seiner Datei. Deine übrigen Änderungen bleiben als Handänderung erhalten, künftige Vanilla-Änderungen werden eingemischt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.defaults", "Die Vorlage schaltet „Bestehende Blöcke übernehmen“ und „Zeilen ganz oder gar nicht“ von Anfang an ein. So wird kein Gebäude halb umgebaut: Kann ein Gebäude nicht umgebaut werden, bleiben auch seine Slots und Holdings unverändert.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.topUp", "Ein Rezept aus einer Vorlage bekommt neue Regeln der Vorlage nicht von selbst. „Fehlendes aus der Vorlage ergänzen“ (Reiter Regeln, unter der Regelliste) zeigt, was dem Rezept fehlt: Regeln, Spalten, Bearbeitungen in vorhandenen Regeln und Wächter-Suchmuster. Nach Rückfrage ergänzt PMT nur das. Vorhandene Regeln, Handänderungen und ausgeschaltete Regeln bleiben unverändert; eine Bearbeitung, die du gelöscht hast, kommt wieder.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset.limits", "Grenzen:\n• Specials ohne Ort in der History (z. B. generische Minen, Lustschloss, Verbotene Stadt) bleiben Special: Ihren Slot vergibt ein Script (Event, Entscheidung, Großprojekt), das das Gebäude gleich mitbaut. Der Einlesen-Dialog zeigt „kein Ort“ und lässt sie nicht wählen; eine solche Zeile im Rezept ist rot („provinz: nicht gefunden“) und wird von allen Regeln ausgelassen.\n• Zeilen späterer Ausbaustufen in der History (z. B. special_building = holy_site_canterbury_cathedral_02) deckt die Regel slots nicht ab; der Wächter zeigt sie.\n• Gebäude, die die History schon zu Spielstart setzt, fehlen nach dem Umbau zu Spielstart.")),
        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.preset2.heading", "Vorlage: Ressourcen in Special Buildings")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.preset2.text", "Fügt Ressourcen-Effekte in Special Buildings ein, ohne sie umzuwandeln; ob ein Gebäude einen Ort in der History hat, spielt keine Rolle. Gedacht für Specials, die Special bleiben, weil ihr Slot ein Script vergibt (z. B. generische Minen, Lustschloss). Die Vorlage hat nur eine Regel „Block bearbeiten“: Sie fügt in on_start die Effekte flogis_techmod_subtract_wood/stone/metal/luxury_250 und in on_cancelled flogis_techmod_add_wood/stone/metal/luxury_250 ein, in allen Stufen der Kette und direkt in den bestehenden Dateien. „Specials aus Vanilla einlesen“ listet alle Specials, die eine Kette beginnen. Specials, die die Vorlage „Special Buildings in normale Gebäude“ umwandelt, bekommen die Effekte schon dort; nimm sie hier nicht zusätzlich auf. Die Effekte gehören zur Mod „Flogi's Buildings and Technology Mod“; ändere sie in der Regel, wenn du sie nicht brauchst.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.adoptMod.heading", "Bestehende Mod-Gebäude übernehmen")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.intro", "Hat deine Mod Vanilla-Gebäude früher unter eigenem Namen kopiert (z. B. flogis_techmod_special_building_1_0 für holy_site_cathedral_01), benennt „Bestehende Mod-Gebäude übernehmen“ in der Tabelle sie auf den Vanilla-Schlüssel zurück. Den Vorschlag liest PMT aus deiner Lokalisierung: building_type_<alt> verweist mit $building_type_<vanilla>$ auf den Vanilla-Text. Du siehst je Gebäude den Vorschlag und einen Status; den Vanilla-Schlüssel kannst du ändern. Gesperrt ist eine Zeile, wenn das Ziel schon in deiner Mod definiert ist, wenn Vanilla es in einer Datei definiert, die deine Mod nicht überdeckt, oder wenn zwei Gebäude dasselbe Ziel hätten.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.warning", "Vorsicht: Neue Gebäudeschlüssel machen laufende Spielstände deiner Mod unbrauchbar, bereits gebaute Gebäude verschwinden. PMT fragt vorher nach. Vermerke die Umbenennung im Changelog deiner Mod.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.where", "Umbenannt wird in allen Dateien deiner Mod (.txt, .gui, .yml), nur ganze Wörter. Abgeleitete Namen wie building_<schlüssel>, building_type_<schlüssel>, <schlüssel>_desc oder has_variable = <schlüssel> zählen mit; ein längerer Schlüssel wie <schlüssel>_2 bleibt. Mit „Kommentar # was: <alter Schlüssel> einfügen“ steht in jedem umbenannten Block als erste Zeile der alte Name. Der Kommentar wandert mit, wenn der Block später in den erzeugten Bereich kommt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.loc", "Die Lokalisierung räumt PMT gleich mit auf, je Sprache. Für jede Zeile, deren Schlüssel sich ändert, gilt:")),
        new GuideBlock(GuideBlockKind.Example, T("patchhelp.adoptMod.locBox", "nur Selbstverweis       building_type_x: \"$building_type_x$\"  -> Zeile weg, Vanilla-Text gilt\nSelbstverweis + Text   \"$cost$$building_type_x_desc$\"       -> Vanilla-Text eingesetzt\nschon vorhanden        gleicher Text: Zeile weg; anderer Text: Warnung\nVanilla hat Schlüssel  -> localization/<sprache>/replace/pmt_renamed_l_<sprache>.yml")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.rows", "Nach dem Anwenden kommen die umbenannten Gebäude als Zeilen in die Tabelle, aber nur Vanilla-Specials am Anfang einer Ausbaukette mit Ort in der History. Die Spalte holdings übernimmt PMT aus den heutigen Listen deiner 00_holdings.txt. Danach zeigt die Vorschau den Rezeptlauf: Er übernimmt die Blöcke wie „Bestehende Blöcke übernehmen“, deine Werte bleiben als Handänderung erhalten. Lokalisierungs-Schlüssel alter Stufen ohne Gebäude (z. B. building_<alt>_1, wenn nur _0 existiert) ändert PMT nicht; die Anzahl steht im Fenster.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.undo", "Strg+Z nimmt die Umbenennung der Dateien zurück, aber nicht die neuen Tabellenzeilen. Entferne sie dann von Hand, sonst legt der nächste Rezeptlauf Vanilla-Kopien neben die alten Schlüssel.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.adoptMod.after", "Danach: Vanilla-Scripts mit add_special_building oder has_special_building zeigen nun auf umgewandelte Gebäude. Der Wächter meldet sie als neue Treffer, und die Regel slots kopiert mehr History-Dateien. Prüfe beides nach dem ersten Rezeptlauf.")),

        new GuideBlock(GuideBlockKind.Heading, T("patchhelp.trouble.heading", "Mein Rezept wirkt nicht")),
        new GuideBlock(GuideBlockKind.Paragraph, T("patchhelp.trouble.list", "• Eine Datei fehlt in der Vorschau: Prüfe das Dateien-Muster. Pfade beginnen im Spielordner (common/…), ** schließt Unterordner ein.\n• Eine Zeile ist rot: Der Grund steht in der Spalte „Hinweis“.\n• „bereits definiert in …“: Der Schlüssel steht schon an anderer Stelle der Mod. PMT erzeugt ihn nicht doppelt. Nutze „Bestehende Blöcke übernehmen“ (Knopf in der Vorschau): PMT holt deinen Block in den erzeugten Bereich, baut ihn um und behält deine Änderungen.\n• Eine Regel ändert nichts: Ist „Aktiv“ angehakt? Suchart „Text“ trifft nur ganze Wörter.\n• „leerer Wert für …“: Die Zeile hat in einer benutzten Spalte keinen Wert und auch keinen Standardwert.\n• Im Zweifel: „Ergebnis zeigen“ für eine einzelne Zeile.")),
    };

    private static PatchRecipeHelpWindow? _open;

    private PatchRecipeHelpWindow()
        : base(T("patchhelp.title", "Anleitung: Patch-Rezepte"), Blocks, withNavigation: true)
    {
    }

    /// <summary>Höchstens ein Anleitungsfenster; ein offenes wird nach vorn geholt. Mit <paramref name="section"/> springt es zum Kapitel (z. B. F1 im KI-Fenster).</summary>
    public static void Show(Window owner, string? section)
    {
        if (_open is null)
        {
            _open = new PatchRecipeHelpWindow { Owner = owner };
            _open.Closed += (_, _) => _open = null;
            _open.Show();
        }
        else
        {
            _open.Activate();
        }

        if (section is not null)
        {
            _open.ShowSection(section);
        }
    }

    // Nur UiText.Get, kein Format: die Texte enthalten geschweifte Klammern ({key}, buildings = { … }).
    private static string T(string key, string german) => UiText.Get(key, german);
}
